        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Create a DP table to store the maximum values collected on two paths
    dp = [[[0, 0] for _ in range(N)] for _ in range(N)]

    # Iterate through the grid to fill the DP table
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                dp[0][0][0] = grid[0][0]
                dp[0][0][1] = 0
            else:
