def cantor_numbering(N: int) -> str:
    numerator = 1
    denominator = 1
    direction = 1
    current_position = 1

    while current_position < N:
        if direction == 1:
            if numerator + 1 + denominator > N:
                numerator = N - sum(range(1, denominator))
            else:
                numerator += 1
                denominator += 1
        else:
            if numerator + 1 + denominator > N:
                denominator = N - sum(range(1, numerator))
            else:
                numerator += 1
                denominator += 1
        direction *= -1
        current_position += 1

    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    level = 1
    total = 0
    while total + level <= N:
        total += level
        level += 1
    level -= 1
    N -= total
    if level % 2 == 0:
        return f"{N}/{level - N + 1}"
    else:
        return f"{level - N + 1}/{N}"

def cantor_numbering(N: int) -> str:
    if N <= 0:
        return "0/0"

    level = 1
    count = 0

    while count + level < N:
        count += level
        level += 1

    position = N - count - 1

    if level % 2 == 0:
        numerator = position + 1
        denominator = level - position
    else:
        numerator = level - position
        denominator = position + 1

    return f"{numerator}/{denominator}"

def cantor_numbering(N: int) -> str:
    if N == 1:
        return "1/1"
    level = 0
    while N > (level + 1) * level // 2:
        N -= (level + 1) * level // 2
        level += 1

    if level % 2 == 0:
        numerator = N
        denominator = level + 1 - N
    else:
        numerator = level + 1 - N
        denominator = N

    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    # Split the number string based on K multiplication signs
    parts = []
    temp = ""
    mul_count = 0
    for char in num_str:
        if char == 'x':
            mul_count += 1
            if mul_count == K + 1:
                parts.append(temp)
                temp = ""
            else:
                parts.append(temp)
                temp = ""
        else:
            temp += char
    parts.append(temp)

    # Convert parts to integers and calculate the product
    product = 1
    for part in parts:
        product *= int(part)

    return product

def max_product(num_str: str, N: int, K: int) -> int:
    from itertools import combinations

    num_list = [int(num_str[i:i+1]) for i in range(N)]
    max_product_value = 0

    for indices in combinations(range(1, N), K):
        temp_list = num_list[:]
        for index in sorted(indices, reverse=True):
            temp_list.insert(index, 0)
        product = 1
        for num in temp_list:
            if num == 0:
                product = 0
                break
            product *= num
        if product > max_product_value:
            max_product_value = product

    return max_product_value

def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, k):
        if k == 0:
            return int(num_str[i:])
        product = 0
        for j in range(i, min(i + K, N - 1)):
            product = max(product, int(num_str[i:j + 1]) * dp(j + 1, k - 1))
        return product

    return dp(0, K)

