def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_aisle_counts = [0] * M
    col_aisle_counts = [0] * N

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:  # Same row, vertical aisle needed
            if min(Yi, Qi) < N - 1:
                col_aisle_counts[min(Yi, Qi)] += 1
                col_aisle_counts[min(Yi, Qi) + 1] += 1
        if Yi == Qi:  # Same column, horizontal aisle needed
            if min(Xi, Pi) < M - 1:
                row_aisle_counts[min(Xi, Pi)] += 1
                row_aisle_counts[min(Xi, Pi) + 1] += 1

    selected_rows = []
    for i in range(M - 1):
        if row_aisle_counts[i] > 0:
            selected_rows.append(i)
    selected_rows.sort()

    selected_cols = []
    for i in range(N - 1):
        if col_aisle_counts[i] > 0:
            selected_cols.append(i)
    selected_cols.sort()

    if K > len(selected_rows):
        selected_rows = sorted(range(M - 1), key=lambda x: min(row_aisle_counts[x], row_aisle_counts[x + 1]), reverse=True)[:K]
    if L > len(selected_cols):
        selected_cols = sorted(range(N - 1), key=lambda x: min(col_aisle_counts[x], col_aisle_counts[x + 1]), reverse=True)[:L]

