def count_passing_ways(n: int, m: int) -> int:
    if m == 0:
        return 1
    if n == 1:
        return 0

    dp = [[0] * 2 for _ in range(m + 1)]
    dp[0][0] = dp[0][1] = 1

    for _ in range(1, m + 1):
        dp[_][0] = dp[_ - 1][1]
        dp[_][1] = dp[_ - 1][0] + dp[_ - 1][1]

    return dp[m][0]

