    dp[0][n] = 1
    for i in range(1, m + 1):
        dp[i][1] = dp[i-1][2]
        dp[i][n] = dp[i-1][n-1]
        for j in range(2, n):
            dp[i][j] = dp[i-1][j-1] + dp[i-1][j+1]
    return dp[m][1]

