    dp[0][1], dp[1][1] = 1, 1
    for k in range(2, m + 1):
        dp[0][k] = dp[1][k - 1]
        dp[1][k] = dp[0][k - 1]
    for i in range(2, n):
        dp[i][1] = 2
    for i in range(2, n):
        for k in range(2, m + 1):
            dp[i][k] = dp[(i - 1) % n][k - 1] + dp[(i + 1) % n][k - 1]
    return dp[0][m]

def count_passing_ways(n: int, m: int) -> int:
    # Initialize a 2D list (dp) to store the number of ways to pass the ball
    dp = [[0 for _ in range(m + 1)] for _ in range(n)]

    # Base case: There's one way to pass the ball 0 times (the ball is with the starting student)
    for i in range(n):
        dp[i][0] = 1

    # Fill the dp array using the recurrence relation
    for k in range(1, m + 1):
        for i in range(n):
            dp[i][k] = dp[(i - 1) % n][k - 1] + dp[(i + 1) % n][k - 1]

    # The result is the number of ways to pass the ball m times and return to the starting student
    return dp[0][m]

