def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D list to store the maximum importance at each budget level
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp table
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        for j in range(1, n + 1):
            if price <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - price] + price * importance)
            else:
                dp[i][j] = dp[i - 1][j]

    # The maximum importance at the budget limit
    return dp[m][n]

