def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a DP array to keep track of the maximum volume that can be occupied by volumes j or less
    dp = [0] * (V + 1)

    # Iterate over each item volume
    for volume in volumes:
        # Update the DP array from back to front to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            dp[j] = max(dp[j], dp[j - volume] + volume)

    # The minimum remaining space is the total capacity minus the maximum occupied volume
    return V - dp[V]

