def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key = key.lower()
    ciphertext = ciphertext.lower()
    plaintext = []
    key_len = len(key)

    for i in range(len(ciphertext)):
        key_idx = i % key_len
        shift = ord(key[key_idx]) - ord('a')
        if 'a' <= ciphertext[i] <= 'z':
            decrypted_char = chr((ord(ciphertext[i]) - ord('a') - shift) % 26 + ord('a'))
        else:
            decrypted_char = ciphertext[i]
        plaintext.append(decrypted_char)

    return ''.join(plaintext).upper()

