def extended_gcd(a, b):
    """Apply the Extended Euclidean Algorithm to find the greatest common divisor of `a` and `b`, and the coefficients of Bézout's identity."""
    if a == 0:
        return (b, 0, 1)
    else:
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return (g, x, y)

